.ch-conclusion-scope {
  --ink: #0F172A;
  --muted: #64748B;
  --accent: #06B6D4;
  --warm: #D97706;
  --line: #E2E8F0;
  --paper: #F8FAFC;
  --danger: #EF4444;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  padding: 2rem;
  box-sizing: border-box;
}

.ch-conclusion-scope * {
  box-sizing: border-box;
}

.chapter-section {
  margin-bottom: 3rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 2rem;
}

.chapter-section:last-child {
  border-bottom: none;
}

.section-title {
  font-size: 1.5rem;
  color: var(--ink);
  margin-bottom: 1.5rem;
  border-left: 4px solid var(--accent);
  padding-left: 1rem;
}

.lead-text {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.trilemma-list {
  list-style: none;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1rem;
}

.trilemma-item {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1rem;
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.prop-label {
  font-weight: bold;
  color: var(--accent);
  font-size: 0.9rem;
}

.prop-text {
  font-size: 1rem;
  color: var(--ink);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.8rem;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  cursor: pointer;
  align-self: flex-start;
  margin-top: 0.5rem;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.notation-reference {
  margin-top: 2rem;
  background: #fff;
  border: 1px solid var(--line);
  padding: 1rem;
  border-radius: 4px;
}

.notation-reference h3 {
  font-size: 1rem;
  margin-top: 0;
  color: var(--muted);
}

.table-container {
  overflow-x: auto;
}

.interaction-workbench {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  border-radius: 8px;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .interaction-workbench {
    grid-template-columns: 1fr;
  }
}

.control-panel h3 {
  margin-top: 0;
  font-size: 1.1rem;
}

.instruction {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.input-group label {
  font-size: 0.9rem;
  font-weight: bold;
}

.input-group input {
  padding: 0.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 1rem;
}

.action-btn {
  padding: 0.5rem 1rem;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

.action-btn.secondary {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
}

.action-btn:hover {
  opacity: 0.9;
}

.feedback-msg {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5rem;
  color: var(--muted);
}

.feedback-msg.error {
  color: var(--danger);
}

.visual-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pie-chart-container {
  width: 200px;
  height: 200px;
  position: relative;
}

.credence-pie {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.pie-slice {
  stroke: #fff;
  stroke-width: 2;
  transition: d 0.5s ease;
}

.pie-label {
  transform: rotate(90deg);
  font-weight: bold;
}

.legend {
  margin-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.conclusion-box {
  background: var(--ink);
  color: #fff;
  padding: 1.5rem;
  border-radius: 8px;
  text-align: center;
  border: 2px solid var(--accent);
}

.conclusion-box.hidden {
  display: none;
}

.conclusion-text {
  font-family: serif;
  font-style: italic;
  font-size: 1.1rem;
  margin: 1rem 0;
}

.conclusion-cn {
  font-size: 1rem;
  color: var(--accent);
  margin-bottom: 1rem;
}

.conclusion-box .source-btn {
  border-color: var(--accent);
  color: var(--accent);
}

@media (prefers-reduced-motion: reduce) {
  .pie-slice {
    transition: none;
  }
}
