(function() {
  const scope = document.querySelector('.ch-conclusion-scope');
  if (!scope) return;

  // State
  let credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
  let isBalanced = true;

  // Elements
  const inputEl = scope.querySelector('#credence-input');
  const applyBtn = scope.querySelector('#apply-info-btn');
  const resetBtn = scope.querySelector('#reset-credence-btn');
  const feedbackEl = scope.querySelector('#feedback-msg');
  const conclusionBox = scope.querySelector('#final-conclusion');
  const slice1 = scope.querySelector('#pie-slice-1');
  const slice2 = scope.querySelector('#pie-slice-2');
  const slice3 = scope.querySelector('#pie-slice-3');
  const tableContainer = scope.querySelector('#notation-table-container');

  // Source Buttons
  scope.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const sourceId = btn.getAttribute('data-source');
      if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
        const source = window.paperMindData.sources[sourceId];
        feedbackEl.textContent = `已定位来源：p.${source.page} - "${source.quote.substring(0, 30)}..."`;
        feedbackEl.classList.remove('error');
      } else {
        feedbackEl.textContent = `来源 ${sourceId} 暂未加载`;
        feedbackEl.classList.add('error');
      }
    });
  });

  // Load Notation Table
  function loadNotationTable() {
    if (window.paperMindData && window.paperMindData.tables) {
      const table = window.paperMindData.tables.find(t => t.id === 'p6-notation-table');
      if (table) {
        let html = '<table style="width:100%;border-collapse:collapse;font-size:0.85rem;"><thead><tr style="border-bottom:1px solid var(--line);"><th style="text-align:left;padding:4px;">符号</th><th style="text-align:left;padding:4px;">定义</th></tr></thead><tbody>';
        table.rows.forEach(row => {
          html += `<tr><td style="padding:4px;border-bottom:1px solid var(--line);">${row.values.Symbol}</td><td style="padding:4px;border-bottom:1px solid var(--line);">${row.values.Definition}</td></tr>`;
        });
        html += '</tbody></table>';
        tableContainer.innerHTML = html;
      }
    }
  }
  loadNotationTable();

  // Pie Chart Logic
  function getPiePath(startAngle, endAngle) {
    const x1 = 50 + 45 * Math.cos(startAngle);
    const y1 = 50 + 45 * Math.sin(startAngle);
    const x2 = 50 + 45 * Math.cos(endAngle);
    const y2 = 50 + 45 * Math.sin(endAngle);
    const largeArc = endAngle - startAngle > Math.PI ? 1 : 0;
    return `M 50 50 L ${x1} ${y1} A 45 45 0 ${largeArc} 1 ${x2} ${y2} Z`;
  }

  function updatePie() {
    const a1 = 0;
    const a2 = 2 * Math.PI * credence.p1;
    const a3 = a2 + 2 * Math.PI * credence.p2;

    slice1.setAttribute('d', getPiePath(a1, a2));
    slice2.setAttribute('d', getPiePath(a2, a3));
    slice3.setAttribute('d', getPiePath(a3, 2 * Math.PI));

    if (isBalanced) {
      conclusionBox.classList.remove('hidden');
      feedbackEl.textContent = "当前为理性均衡状态。";
      feedbackEl.classList.remove('error');
    } else {
      conclusionBox.classList.add('hidden');
    }
  }

  // Interaction
  applyBtn.addEventListener('click', () => {
    const val = inputEl.value.trim();
    if (!val) {
      feedbackEl.textContent = "请输入特异性信息。";
      feedbackEl.classList.add('error');
      return;
    }

    // Teaching Example Logic based on text S061 (Meteor)
    if (val.includes('陨石') || val.includes('meteor')) {
      credence = { p1: 0.8, p2: 0.1, p3: 0.1 };
      isBalanced = false;
      feedbackEl.textContent = "教学示例：发现陨石可能增加命题 (1) 权重，但这属于特定证据，非当前默认状态。";
      feedbackEl.classList.remove('error');
    } else if (val.includes('伦理') || val.includes('ethics')) {
      credence = { p1: 0.1, p2: 0.8, p3: 0.1 };
      isBalanced = false;
      feedbackEl.textContent = "教学示例：伦理收敛可能增加命题 (2) 权重，但原文指出当前无确凿证据。";
      feedbackEl.classList.remove('error');
    } else {
      // Default lock
      credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
      isBalanced = true;
      feedbackEl.textContent = "未检测到支持偏向某一分支的特异性证据。在无知黑暗森林中，理性策略维持均匀分配。";
      feedbackEl.classList.remove('error');
    }
    updatePie();
  });

  resetBtn.addEventListener('click', () => {
    inputEl.value = '';
    credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
    isBalanced = true;
    updatePie();
    feedbackEl.textContent = "已复位至均匀分配状态。";
  });

  // Init
  updatePie();

  // Keyboard accessibility for input
  inputEl.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      applyBtn.click();
    }
  });
})();
